TABLEATTRIBUTE.VALUE:
select Infopro_Div_Nbr, Acct_Nbr, Site_Nbr, Sales_Activity_Period_SK, Cur_LOB_Category, Is_ERF_On, Is_FRF_On, Is_ERF_on_FRF, Contract_Term, Estimated_Lift_Cnt from (SELECT dch.Infopro_Div_Nbr, da.Acct_Nbr, ds.Site_Nbr, fsa.Sales_Activity_Period_SK, --- case when Cur_LOB_Category like 'Resi%' and da.Acct_Cat like 'Com%' Then 'Com' --- when Cur_LOB_Category like 'Resi%' and da.Acct_Cat like 'Ind%' Then 'Ind' ---Else left(dch.Cur_LOB_Category,3) end as Cur_LOB_Category,
case when Cur_LOB_Category like 'RES%' and da.Acct_Cat like 'Com%' Then 'Com' when Cur_LOB_Category like 'RES%' and da.Acct_Cat like 'Ind%' Then 'Ind' Else case when Cur_LOB_Category in ('SC Recycling','SC Solid Waste') Then 'Com' when Cur_LOB_Category in ('LC Recycling','LC Solid Waste') Then 'Ind' when Cur_LOB_Category in ('RES Recycling','RES Solid Waste','RES Yard Waste') Then 'Res' end end as Cur_LOB_Category, fsa.Is_ERF_On, fsa.Is_FRF_On, fsa.Is_ERF_on_FRF, ds.Contract_Term, fsa.Estimated_Lift_Cnt, ROW_NUMBER() over(PARTITION by dch.Infopro_Div_Nbr, da.Acct_Nbr, ds.Site_Nbr, fsa.Sales_Activity_Period_SK, case when Cur_LOB_Category like 'RES%' and da.Acct_Cat like 'Com%' Then 'Com' when Cur_LOB_Category like 'RES%' and da.Acct_Cat like 'Ind%' Then 'Ind' Else case when Cur_LOB_Category in ('SC Recycling','SC Solid Waste') Then 'Com' when Cur_LOB_Category in ('LC Recycling','LC Solid Waste') Then 'Ind' when Cur_LOB_Category in ('RES Recycling','RES Solid Waste','RES Yard Waste') Then 'Res' end end order by fsa.Create_Dt_SK desc,fsa.Eff_Dt_SK desc) rn FROM dwcore.dbo.Fact_Sales_Activity fsa with (nolock) JOIN dwcore.dbo.Dim_Corp_Hier dch with (nolock) ON dch.Corp_Hier_SK = fsa.Corp_Hier_SK JOIN dwcore.dbo.Dim_Sales_Activity_Hier hier with (nolock) ON hier.Activity_Reason_SK = fsa.Activity_Reason_SK JOIN dwcore.dbo.Dim_Container_Grp dcg with (nolock) ON dcg.container_grp_sk = fsa.container_grp_sk JOIN dwcore.dbo.Dim_Acct da with (nolock) ON da.Acct_SK = fsa.Acct_SK JOIN dwcore.dbo.Dim_Site ds with (nolock) ON ds.Site_SK = fsa.Site_SK join Dim_Txn_Reason_Cd txn with (nolock) on txn.Txn_Reason_Cd_SK=fsa.Txn_Reason_Cd_SK WHERE ((Lvl_1='Sales Activity' and Lvl_2='Open Market' and Lvl_3='New') ) and txn.Txn_Cd='01' and txn.Reason_Cd in ('01','02') AND is_updated = 0 AND is_deleted = 0 AND ( cur_lob_category LIKE 'LC%' OR cur_lob_category LIKE'SC%' OR (Cur_LOB_Category like 'RES%' and da.Acct_Cat like 'Com%') OR (Cur_LOB_Category like 'RES%' and da.Acct_Cat like 'Ind%') ) AND is_Updated = 0 AND is_Deleted = 0 AND Sales_Activity_Period_SK >= 201410 AND (fsa.Monthly_Sales_Change_Amt != 0 OR fsa.Revenue_Expect_Disposal_Change_Amt != 0 OR fsa.Monthly_Lift_Change_Cnt != 0 OR fsa.Monthly_Yard_Change_Cnt != 0 )
)FSA where rn=1

TRANSFORMFIELD.EXPRESSION:
IIF(IIF(ISNULL(Txn_Cd),'',Txn_Cd) != '',
IIF(Txn_Cd = '01',Container_Cnt,
IIF(Txn_Cd = '04',Container_Cnt * -1,
IIF(Txn_Cd = '02' AND SDFLG1 = 'Y',Container_Cnt,
IIF(Txn_Cd = '02' AND SDFLG1 = 'N',Container_Cnt - SDOQTY,
IIF((Txn_Cd = '07' OR Txn_Cd = '08' OR Txn_Cd = '03' OR Txn_Cd = '06'),0,
IIF(Txn_Cd = '05',Container_Cnt - SDOQTY,0)
)
)
)
)
),0)
